const ASANA_COLORS = {
  'red': [219,47,51], 'orange': [255,140,0], 'yellow-orange': [255,179,71],
  'yellow': [255,214,0], 'yellow-green': [163,199,40], 'green': [61,174,87],
  'blue-green': [0,168,150], 'aqua': [0,188,212], 'blue': [66,133,244],
  'indigo': [63,81,181], 'purple': [156,39,176], 'magenta': [216,27,96],
  'hot-pink': [255,64,129], 'pink': [244,143,177], 'cool-gray': [144,155,165]
};

function nearestColor(hex) {
  if (!hex) return 'none';
  const c = hex.replace('#', '');
  const r = parseInt(c.slice(0,2), 16);
  const g = parseInt(c.slice(2,4), 16);
  const b = parseInt(c.slice(4,6), 16);
  let best = 'blue', min = Infinity;
  for (const [name, [cr, cg, cb]] of Object.entries(ASANA_COLORS)) {
    const d = (r-cr)**2 + (g-cg)**2 + (b-cb)**2;
    if (d < min) { min = d; best = name; }
  }
  return best;
}

return items.map(item => {
  const enumOptions = item.json.type_config.options
    .sort((a, b) => Number(a.orderindex) - Number(b.orderindex))
    .map(opt => ({ name: opt.name, color: nearestColor(opt.color), enabled: true }));
  return { json: { ...item.json, asanaEnumOptions: enumOptions } };
});

