return items.map(item => {
  const count = Number(item.json.type_config.count) || 5;
  const enumOptions = [];
  for (let i = 1; i <= count; i++) {
    enumOptions.push({ name: String(i), color: GRADIENT[i - 1] || 'blue', enabled: true });
  }
  return { json: { ...item.json, asanaEnumOptions: enumOptions } };
});

