const items = $input.all();

// dedupe by id (include_timl can return a task once per list)
const seen = new Set();
const tasks = [];
items.forEach((it, i) => {
  if (seen.has(it.json.id)) return;
  seen.add(it.json.id);
  tasks.push({ json: it.json, idx: i });
});

const byId = new Map(tasks.map(t => [t.json.id, t.json]));

// depth 0 = top-level, 1 = subtask, 2 = sub-subtask...
// a parent that isn't in this batch (already migrated) counts as depth 1
const depthOf = (task) => {
  let depth = 0, cur = task;
  const guard = new Set();
  while (cur && cur.parent && !guard.has(cur.id)) {
    guard.add(cur.id);
    depth++;
    cur = byId.get(cur.parent);
  }
  return depth;
};

// pairedItem keeps item linking intact when dedupe changes the item count
return tasks
  .map(t => ({ json: { ...t.json, depth: depthOf(t.json) }, pairedItem: { item: t.idx } }))
  .sort((a, b) => a.json.depth - b.json.depth);

